/* GENERATED by src/agents/unit_test_agent - review before relying on it.
 *
 * Requirement IF-004: The SH1106 driver shall apply a 2-column offset when writing the logo and all other screens to account for its 132 columns of RAM and 128 visible columns.
 * Verified by: host test
 * Derived from: firmware/drivers/sh1106/sh1106.c, firmware/platforms/stm32/platform_io.c, firmware/services/display.c, sources/PRD.md
 * Rationale: The acceptance criterion requires visible column c to be written at RAM column c+2, with the offset applied once, for both logo and non-logo screens. In sh1106.c:12-35, sh1106_page sets the column address in its four-byte command using RAM_OFFSET=2, then sends the 128 pixel bytes in two unchanged chunks; the test checks that command and both chunks for separate logo/non-logo page data.
 */

#include "unity.h"
#include "sh1106.h"
#include <string.h>

static uint8_t captured_bytes[6][65];
static uint16_t captured_lengths[6];
static unsigned int captured_calls;

static bool capture_send(uint8_t address, uint8_t *bytes, uint16_t length)
{
    (void)address;
    if ((captured_calls >= 6U) || (length > sizeof(captured_bytes[0])))
    {
        return false;
    }
    memcpy(captured_bytes[captured_calls], bytes, length);
    captured_lengths[captured_calls] = length;
    captured_calls++;
    return true;
}

void setUp(void)
{
    memset(captured_bytes, 0, sizeof(captured_bytes));
    memset(captured_lengths, 0, sizeof(captured_lengths));
    captured_calls = 0U;
}

void tearDown(void)
{
}

void test_IF_004_01(void)
{
    uint8_t logo_pixels[128];
    uint8_t screen_pixels[128];
    uint8_t expected_logo_command[4] = {0x00U, 0xB0U, 0x02U, 0x10U};
    uint8_t expected_screen_command[4] = {0x00U, 0xB3U, 0x02U, 0x10U};

    for (uint16_t column = 0U; column < 128U; column++)
    {
        logo_pixels[column] = (uint8_t)(column ^ 0x5AU);
        screen_pixels[column] = (uint8_t)(column ^ 0xA5U);
    }

    /* Exercise the same page writer with logo and non-logo screen contents. */
    TEST_ASSERT_TRUE(sh1106_page(capture_send, 0x3CU, 0U, logo_pixels));
    TEST_ASSERT_TRUE(sh1106_page(capture_send, 0x3CU, 3U, screen_pixels));
    TEST_ASSERT_EQUAL_UINT32(6U, captured_calls);

    /* Each screen's page command selects RAM column 2 exactly once; its 128
     * pixel bytes are then sent unchanged, mapping visible c to RAM c + 2. */
    TEST_ASSERT_EQUAL_UINT16(4U, captured_lengths[0]);
    TEST_ASSERT_EQUAL_MEMORY(expected_logo_command, captured_bytes[0], sizeof(expected_logo_command));
    TEST_ASSERT_EQUAL_UINT16(65U, captured_lengths[1]);
    TEST_ASSERT_EQUAL_UINT16(65U, captured_lengths[2]);
    TEST_ASSERT_EQUAL_MEMORY(logo_pixels, &captured_bytes[1][1], 64U);
    TEST_ASSERT_EQUAL_MEMORY(&logo_pixels[64], &captured_bytes[2][1], 64U);

    TEST_ASSERT_EQUAL_UINT16(4U, captured_lengths[3]);
    TEST_ASSERT_EQUAL_MEMORY(expected_screen_command, captured_bytes[3], sizeof(expected_screen_command));
    TEST_ASSERT_EQUAL_UINT16(65U, captured_lengths[4]);
    TEST_ASSERT_EQUAL_UINT16(65U, captured_lengths[5]);
    TEST_ASSERT_EQUAL_MEMORY(screen_pixels, &captured_bytes[4][1], 64U);
    TEST_ASSERT_EQUAL_MEMORY(&screen_pixels[64], &captured_bytes[5][1], 64U);
}
